  ('bruxaria', 'Bruxaria', 'Fundamentos, ética e rituais', 'O caminho da bruxa moderna: altar, intenção, ciclos lunares, proteção e os primeiros rituais.', 'vela', '#E08A4F', 2, true),
  ('bruxaria-natural', 'Bruxaria natural', 'A magia do quintal e das estações', 'Ervas, pedras, água e fogo: a bruxaria que nasce da terra, da roda do ano e do que cresce perto de você.', 'folha', '#8FB573', 3, true),
  ('chas', 'Chás medicinais', 'Preparos, combinações e cuidados', 'Infusão, decocção e maceração. Quais plantas, quanto e quando. Conteúdo educativo e tradicional: não substitui orientação médica. Gestantes, lactantes e quem usa remédios contínuos devem consultar um profissional antes de usar qualquer planta.', 'cha', '#D9B26B', 4, true),
  ('cura-plantas', 'Cura pelas plantas', 'Saberes populares e segurança', 'Banhos, compressas, tinturas e unguentos da tradição popular brasileira. Conteúdo educativo e tradicional: não substitui orientação médica. Gestantes, lactantes e quem usa remédios contínuos devem consultar um profissional antes de usar qualquer planta.', 'planta', '#6FAF8F', 5, true),
  ('ocultismo', 'Ocultismo', 'Símbolos, tradições e história', 'Hermetismo, alquimia, cabala e os grandes símbolos do conhecimento oculto, explicados sem mistério desnecessário.', 'olho', '#8C9AD1', 6, true),
  ('angelologia', 'Angelologia', 'Hierarquias, nomes e orações', 'Os coros angélicos, os anjos da guarda, os arcanjos e como cada tradição se relaciona com eles.', 'asas', '#E9D58A', 7, true),
  ('buzios', 'Búzios', 'O jogo, as caídas e os odus', 'A história e o respeito ao jogo de búzios: como as conchas caem, o que dizem e o papel de quem joga.', 'conchas', '#E3B7A0', 8, true)
on conflict (slug) do update set titulo = excluded.titulo, subtitulo = excluded.subtitulo,
  descricao = excluded.descricao, icone = excluded.icone, cor = excluded.cor, ordem = excluded.ordem;

